<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { app, game, gs } from '../session'
import { CONDITIONS, EFFECTS } from '../rules/base'
// name plates, damage numbers and pings, placed by hand every frame
const root = ref<HTMLElement>(); let raf = 0; const els = new Map<string, HTMLElement>()
const mk = (id: string, cls: string, html: string) => { const e = document.createElement('div'); e.className = cls; e.innerHTML = html; root.value!.appendChild(e); els.set(id, e); return e }
onMounted(() => { const tick = () => { raf = requestAnimationFrame(tick); const g = game.value, G = gs.value; if (!g?.world || !root.value) return; const W = g.canvas.clientWidth, H = g.canvas.clientHeight, live = new Set<string>(); const put = (e: HTMLElement, p: { x: number; y: number }) => { e.style.transform = `translate(-50%,-100%) translate(${((p.x + 1) / 2 * W).toFixed(1)}px,${((1 - p.y) / 2 * H).toFixed(1)}px)` }; const cur = G?.combat ? G.combat.order[G.combat.i]?.id : ''
  for (const t of app.tokens) { const a = g.actors.map.get(t.id); if (!a || !a.lit || (t.id === g.me && !g.view.flat)) continue; const h = g.actors.height(a); const m = G?.mons[t.id], hero = G?.chars[t.id]; if (t.hp <= 0 && !hero) { const loot = m && (m.gold || m.loot?.length); if (!loot) continue } const p = g.view.project(a.x, a.y + (a.dead ? .6 : Math.min(h, 3.4)) + .22, a.z, g.aspect); if (!p || Math.abs(p.x) > 1.05 || Math.abs(p.y) > 1.05) continue; const far = !g.view.flat && p.d > 24, hot = app.hover === t.id || app.selToken === t.id || t.id === cur; if (!hot && (far || (g.view.flat && g.view.z > 30))) continue; live.add(t.id); const e = els.get(t.id) ?? mk(t.id, 'tag', '<b></b><i><u></u></i><s></s>'); const dm = app.role === 'dm'; const cs = (t.cond ?? []).filter(c => c !== 'concentrating').slice(0, 3).map(c => (CONDITIONS[c] ?? EFFECTS[c])?.name).filter(Boolean).join(', '); const foe = t.side === 'foe'; const state = foe && !dm ? (t.hp <= 0 ? '' : t.hp < t.max * .25 ? 'near death' : t.hp < t.max * .55 ? 'bloodied' : '') : ''; const key = `${t.name}|${t.hp}|${t.max}|${t.side}|${t.hidden}|${cs}|${hot}|${dm}|${m?.boss}`; if (e.dataset.k !== key) { e.dataset.k = key; e.className = `tag ${t.side}${t.hidden ? ' hid' : ''}${m?.boss ? ' boss' : ''}${t.hp <= 0 ? ' down' : ''}`; e.children[0].textContent = t.name; (e.querySelector('u') as HTMLElement).style.width = Math.max(0, Math.min(1, t.hp / Math.max(1, t.max))) * 100 + '%'; (e.children[1] as HTMLElement).style.display = (foe && !dm && t.hp === t.max && !hot) || t.hp <= 0 || (t.side === 'npc' && !dm) ? 'none' : ''; e.children[2].textContent = [t.hp <= 0 ? (hero ? (hero.dead ? 'dead' : hero.stable ? 'stable' : `dying ${hero.death.s}✓ ${hero.death.f}✗`) : 'loot') : state, cs, dm && hot && t.hp > 0 ? `${t.hp}/${t.max}` : ''].filter(Boolean).join(' · ') } put(e, p) }
  for (const f of app.floats) { const a = g.actors.map.get(f.tok); if (!a) continue; const p = g.view.project(a.x, a.y + Math.min(g.actors.height(a), 3) * .85, a.z, g.aspect); if (!p || Math.abs(p.x) > 1.1) continue; const id = 'f' + f.id; live.add(id); let e = els.get(id); if (!e) { e = mk(id, 'fl', '<span></span>'); e.children[0].className = f.cls; e.children[0].textContent = f.text; (e.children[0] as HTMLElement).style.setProperty('--dx', ((f.id % 5) - 2) * 13 + 'px') } put(e, p) }
  for (const q of app.pings) { const p = g.view.project(q.x, q.y + .4, q.z, g.aspect); if (!p) continue; const id = 'ping' + q.id; live.add(id); let e = els.get(id); if (!e) { e = mk(id, 'ping', '<span></span>'); e.style.setProperty('--c', q.color); e.children[0].textContent = q.who } e.style.transform = `translate(-50%,-50%) translate(${((p.x + 1) / 2 * W).toFixed(1)}px,${((1 - p.y) / 2 * H).toFixed(1)}px)` }
  for (const [k, e] of els) if (!live.has(k)) { e.remove(); els.delete(k) } }; tick() }); onBeforeUnmount(() => cancelAnimationFrame(raf))
</script>
<template><div ref="root" class="tags" /></template>
<style>
.tags{position:absolute;inset:0;overflow:hidden;pointer-events:none!important}.tag{position:absolute;left:0;top:0;display:grid;justify-items:center;gap:0;white-space:nowrap;will-change:transform}.tag b{font:600 14px/1 var(--ui);color:#fff;background:#14263de0;padding:3px 7px 4px}.tag i{width:100%;min-width:46px;height:5px;background:#0c1828;overflow:hidden}.tag u{display:block;height:100%;background:#57b37f;transition:width .3s}.tag.foe u{background:#e0533f}.tag.foe b{background:#8e2418e8}.tag.hero b{background:#15171be0}.tag.npc b{background:#f1f0eaf0;color:#15171b}.tag.boss b{font:700 19px/1 var(--serif);padding:4px 11px 6px}.tag.boss i{height:8px}.tag.hid{opacity:.55}.tag.down b{opacity:.7}.tag s{text-decoration:none;font:500 13px/1.15 var(--ui);color:#15171b;background:#f1f0ea;padding:1px 6px}.tag s:empty{display:none}
.fl{position:absolute;left:0;top:0;will-change:transform}.fl span{display:block;font:800 22px/1 var(--serif);color:#fff;-webkit-text-stroke:5px #14202e;paint-order:stroke fill;animation:flup 1.45s ease-out forwards}.fl .dmg{color:#ff7a5e;font-size:34px}.fl .heal{color:#8ff0b0;font-size:31px}.fl .miss{color:#e4e3da;font-size:20px}.fl .crit{color:#ffd23f;font-size:31px}.fl .good{color:#a8d8ff;font-size:19px}.fl .bad{color:#ffb3a1;font-size:19px}.fl .fire{color:#ff9d3f}.fl .cold{color:#a5dcff}.fl .radiant{color:#ffe27a}.fl .necrotic{color:#cfa0f0}.fl .poison,.fl .acid{color:#bfe86a}.fl .lightning{color:#b9c9ff}@keyframes flup{0%{transform:translate(var(--dx),10px) scale(.6);opacity:0}14%{transform:translate(var(--dx),0) scale(1.12);opacity:1}70%{opacity:1}100%{transform:translate(var(--dx),-46px) scale(1);opacity:0}}
.ping{position:absolute;left:0;top:0;width:64px;height:64px;display:grid;place-items:center}.ping::before,.ping::after{content:'';position:absolute;inset:0;border-radius:50%;border:4px solid var(--c);animation:png 1.2s ease-out infinite}.ping::after{animation-delay:.6s}.ping span{font:600 14px var(--ui);color:#fff;background:#14263de0;padding:2px 8px;margin-top:84px}@keyframes png{from{transform:scale(.15);opacity:1}to{transform:scale(1.25);opacity:0}}
</style>
